css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); position: relative; }
.loader::before, .loader::after { content: ''; position: absolute; top: 50%; width: calc(var(--loader-size) * .06); height: 56%; margin-top: -28%; border-radius: calc(var(--loader-size) * .03); background: var(--accent); }
.loader::before { left: 0; animation: paddle-l calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader::after { right: 0; animation: paddle-r calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span { position: absolute; top: 50%; left: 10%; width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); margin-top: calc(var(--loader-size) * -.05); border-radius: 50%; background: var(--accent-2); animation: ball calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
@keyframes ball { 0%, 100% { left: 10%; top: 30%; } 50% { left: 78%; top: 60%; } }
@keyframes paddle-l { 0%, 100% { transform: translateY(-18%); } 50% { transform: translateY(14%); } }
@keyframes paddle-r { 0%, 100% { transform: translateY(14%); } 50% { transform: translateY(-18%); } }
